    ((SELECT id FROM topics WHERE slug = 'ent-nose' LIMIT 1), 'Which of the following represents a "major" symptom criteria for the diagnosis of acute rhinosinusitis under the AAO-HNS guidelines?', '["Halitosis", "Headache", "Purulent nasal discharge", "Ear pain/fullness", "Cough"]'::jsonb, 2, 'Major criteria include: purulent anterior nasal discharge, purulent nasal blockage/obstruction, facial congestion/fullness, facial pain/pressure, and hyposmia/anosmia. Minor criteria include headache, fever, halitosis, fatigue, dental pain, cough, and ear pain/fullness.'),
